package com.letstudy.backend.controller;
import com.letstudy.backend.model.Subject; import com.letstudy.backend.repository.SubjectRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/subjects") public class SubjectController {private final SubjectRepository repo; public SubjectController(SubjectRepository repo){this.repo=repo;} @GetMapping public List<Subject> all(){return repo.findAll();} @GetMapping("/{id}") public Subject one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping public Subject add(@RequestBody Subject s){s.setId(null);return repo.save(s);} @PutMapping("/{id}") public Subject update(@PathVariable Long id,@RequestBody Subject input){Subject s=repo.findById(id).orElseThrow();s.setName(input.getName());s.setDescription(input.getDescription());return repo.save(s);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
